/*
 * Firebase (Google Analytics for Firebase + Crashlytics, @react-native-firebase 26) for the native
 * customer app, config-plugin only (android/ is generated by `expo prebuild` and gitignored).
 * "@react-native-firebase/app" and "@react-native-firebase/crashlytics" (listed in app.json before
 * this plugin) already add the google-services and Crashlytics Gradle plugins; this one only does
 * what they do not:
 *
 *  - Crashlytics' Gradle plugin uploads the R8 mapping file to Firebase at the end of every
 *    minified release build, which needs the network and a Firebase login at build time. That upload
 *    is switched OFF here, so a local or offline `gradlew assembleRelease` never depends on it
 *    (Play Console still gets the mapping from the AAB for its own Android vitals). To upload a
 *    mapping on purpose (readable Java/Kotlin stacks in Crashlytics), build with
 *    `-PblynkCrashlyticsMapping=true` (or BLYNK_CRASHLYTICS_MAPPING=true) while online.
 *
 * Idempotent. The pure helper is exported for the test (src/blynk/lib/withBlynkFirebase.test.ts).
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARK = '// blynk-crashlytics-mapping-upload';

const BLOCK = `
${MARK}
// pluginManager.withPlugin: runs whenever the Crashlytics plugin is applied (the line that applies
// it is added by @react-native-firebase/crashlytics, before or after this block)
pluginManager.withPlugin('com.google.firebase.crashlytics') {
    def blynkUploadMapping = "\${findProperty('blynkCrashlyticsMapping') ?: System.getenv('BLYNK_CRASHLYTICS_MAPPING') ?: 'false'}" == 'true'
    android.buildTypes.configureEach { buildType ->
        buildType.firebaseCrashlytics {
            mappingFileUploadEnabled blynkUploadMapping
        }
    }
}
`;

/** Append the mapping-upload switch to app/build.gradle (once). */
function disableMappingUpload(gradle) {
  if (gradle.includes(MARK)) return gradle;
  return `${gradle.replace(/\s*$/, '')}\n${BLOCK}`;
}

function withBlynkFirebase(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language === 'groovy') {
      cfg.modResults.contents = disableMappingUpload(cfg.modResults.contents);
    }
    return cfg;
  });
}

module.exports = withBlynkFirebase;
module.exports.disableMappingUpload = disableMappingUpload;
module.exports.MARK = MARK;
